local s=UV.s;local moved,stayed=0,0;for _,id in ipairs(s.ids) do local u=assert(Players[s.owner]:GetUnitByID(id));assert(not u:IsBusy() and not u:IsFighting(),"Wait for missions");local p=UV.expected[id] and s.target or s.source;assert(u:GetX()==p:GetX() and u:GetY()==p:GetY());assert(u:GetCurrHitPoints()==UV.before[id].hp and u:GetSquadNumber()==UV.before[id].squad and u:CanStackAtPlot(u:GetPlot()));if UV.expected[id] then moved=moved+1 else stayed=stayed+1 end end;assert(moved==7 and stayed==3);for id,v in pairs(UV.original) do local u=assert(Players[s.owner]:GetUnitByID(id));assert(u:GetX()==v.x and u:GetY()==v.y and u:GetCurrHitPoints()==v.hp and u:GetSquadNumber()==v.squad) end;UV.complete=true;print("STACKUI10|ACTUAL_PASS|seven arrived three stayed; all ten HP/Squads/legal caps and originals preserved")
